<?php
require __DIR__ . '/student-access.php';
require __DIR__ . '/notification-common.php';
$uid=(int)$_SESSION['user_id'];
$stmt=$conn->prepare('SELECT notification_id,type,title,message,link_path,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,notification_id DESC LIMIT 100');
$stmt->bind_param('i',$uid);$stmt->execute();$items=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$unread=0;foreach($items as $n){if(!(int)$n['is_read'])$unread++;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications | MIRA</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')==='dark'?'dark':'light'}catch(e){}</script><link rel="stylesheet" href="notification.css"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-student-nav.css?v=2"></head><body class="mira-notification-page"><?php require __DIR__ . "/mira-student-nav.php"; ?><main class="notification-shell"><div class="notification-toolbar"><a href="user-home.php">← Back to MIRA</a><button type="button" id="themeToggle" class="notification-theme">Toggle theme</button></div><header><p class="notification-eyebrow">MIRA · YOUR ACTIVITY</p><h1>Notifications ✦</h1><p>Updates about your artwork and exhibition requests.</p></header><div class="notification-actions"><span><?= $unread ?> unread in your latest 100 notifications</span><?php if($unread):?><form action="notification-action.php" method="post"><input type="hidden" name="csrf" value="<?=miraNotificationEscape(miraNotificationToken())?>"><input type="hidden" name="action" value="all"><button type="submit">Mark all as read</button></form><?php endif;?></div><section class="notification-list" aria-label="Your notifications"><?php if(!$items):?><div class="notification-empty">No notifications yet. When an admin reviews your artwork or exhibition request, updates will appear here.</div><?php endif;?><?php foreach($items as $n):?><article class="notification-card <?= $n['is_read']?'':'unread' ?>"><div class="notification-card-body"><span class="notification-kind"><?=miraNotificationEscape(str_replace('_',' ',ucwords($n['type'],'_')))?></span><h2><?=miraNotificationEscape($n['title'])?></h2><p><?=miraNotificationEscape($n['message'])?></p><small><?=miraNotificationEscape($n['created_at'])?></small></div><div class="notification-card-actions"><?php if(!$n['is_read']):?><form method="post" action="notification-action.php"><input type="hidden" name="csrf" value="<?=miraNotificationEscape(miraNotificationToken())?>"><input type="hidden" name="action" value="read"><input type="hidden" name="notification_id" value="<?=(int)$n['notification_id']?>"><button type="submit">Mark read</button></form><?php endif;?><?php if($n['link_path'] && preg_match('~^(my-artworks\.php|my-events\.php|exhibitions\.php|exhibition-detail\.php\?id=[0-9]+)$~',(string)$n['link_path'])):?><a href="<?=miraNotificationEscape($n['link_path'])?>">View details →</a><?php endif;?></div></article><?php endforeach;?></section></main></body></html>
